import SwiftUI
struct SettingsView:View{@EnvironmentObject var s:TradingStore;var body:some View{NavigationStack{Form{Section("Live Market Data"){SecureField("Twelve Data API key (optional)",text:$s.apiKey);Text(s.apiKey.isEmpty ? "No key: deterministic demo prices. Add a key for live/historical market data." : "API key configured.").font(.caption).foregroundStyle(.secondary)}Section("Momentum / Trend Core"){Stepper("Momentum: \(s.settings.momentumMonths) months",value:$s.settings.momentumMonths,in:3...18);Stepper("Fast EMA: \(s.settings.fastMA)",value:$s.settings.fastMA,in:10...100,step:5);Stepper("Slow EMA: \(s.settings.slowMA)",value:$s.settings.slowMA,in:100...300,step:10);Stepper("Minimum score: \(s.settings.minimumScore)",value:$s.settings.minimumScore,in:50...100,step:5)}Section("Risk"){Stepper("Risk/trade: \(s.settings.riskPct,specifier:"%.1f")%",value:$s.settings.riskPct,in:0.1...3,step:0.1);Stepper("Max position: \(s.settings.maxPositionPct,specifier:"%.0f")%",value:$s.settings.maxPositionPct,in:5...50,step:5);Stepper("Max positions: \(s.settings.maxPositions)",value:$s.settings.maxPositions,in:1...15)}Section("Confirmations"){Toggle("RSI",isOn:$s.settings.useRSI);Toggle("MACD",isOn:$s.settings.useMACD);Toggle("ADX",isOn:$s.settings.useADX);Toggle("Volume",isOn:$s.settings.useVolume)}Section{Button("Reset $10,000 Paper Account",role:.destructive){s.settings.startingCash=10000;s.reset()}}}.navigationTitle("Strategy Lab")}}}
